export const quizzes={short:[{q:'Blue Ribbon Sports’u kimler kurdu?',a:['Phil Knight ve Bill Bowerman','Adi ve Rudolf Dassler','Michael Jordan ve David Falk','Carolyn Davidson ve Phil Knight'],correct:0,why:'Phil Knight ve eski antrenörü Bill Bowerman 1964’te ortaklık kurdu.'},{q:'adidas hangi kasabada kuruldu?',a:['Portland','Herzogenaurach','Chicago','Milano'],correct:1,why:'Adi Dassler şirketini Bavyera’daki Herzogenaurach’ta kaydetti.'},{q:'PUMA’nın kurucusu kimdir?',a:['Adi Dassler','Rudolf Dassler','Phil Knight','Bill Bowerman'],correct:1,why:'Rudolf Dassler 1948’de ayrı şirketini kurdu.'},{q:'Superstar ilk hangi spor için tasarlandı?',a:['Koşu','Tenis','Basketbol','Futbol'],correct:2,why:'adidas Superstar 1970’te basketbol ayakkabısı olarak çıktı.'},{q:'Swoosh’u kim tasarladı?',a:['Carolyn Davidson','Barbara Bowerman','Käthe Dassler','Lina Radke'],correct:0,why:'Portland State öğrencisi Carolyn Davidson Nike’ın işaretini çizdi.'}],long:[{q:'Blue Ribbon Sports’un ilk işi neydi?',a:['Futbol takımı işletmek','Japon koşu ayakkabılarını dağıtmak','Basketbol salonu açmak','Spor yayınları yapmak'],correct:1,why:'İlk dönemde şirket Onitsuka Tiger ayakkabılarını ABD’de dağıtıyordu.'},{q:'adidas şirketi hangi yıl tescil edildi?',a:['1924','1948','1949','1954'],correct:2,why:'Adi Dassler şirketi 18 Ağustos 1949’da kaydetti.'},{q:'PUMA markası hangi yıl doğdu?',a:['1936','1948','1949','1954'],correct:1,why:'PUMA tarihçesi markanın doğuşunu 1948’e tarihler.'},{q:'Air Jordan 1 hangi yıl piyasaya çıktı?',a:['1971','1980','1985','1990'],correct:2,why:'İlk Air Jordan 1985’te satışa sunuldu.'},{q:'Superstar’ın ayırt edici burun detayı nedir?',a:['Kauçuk kabuk burun','Metal krampon','Şeffaf hava tabanı','Fermuar'],correct:0,why:'Shell toe olarak bilinen kauçuk burun modelin imzasıdır.'},{q:'Carolyn Davidson ne okuyordu?',a:['Mimarlık','Grafik tasarım','İşletme','Spor bilimi'],correct:1,why:'Davidson Portland State’te grafik tasarım öğrencisiydi.'},{q:'Dassler kardeşler nerede üretime başladı?',a:['Portland','Herzogenaurach','Milano','Londra'],correct:1,why:'Ortak atölyeleri Herzogenaurach kasabasındaydı.'},{q:'Run-DMC hangi adidas modelini sahiplendi?',a:['Superstar','Copa Mundial','Samba','Stan Smith'],correct:0,why:'Grubun Superstar’ı sahiplenmesi hip-hop bağını güçlendirdi.'},{q:'Bill Bowerman’ın mesleği neydi?',a:['Koşu antrenörü','Grafik tasarımcı','Hakem','Mağazacı'],correct:0,why:'Bowerman Oregon Üniversitesi’nde atletizm antrenörüydü.'},{q:'Üç çizgili adidas işareti ilk nerede yer aldı?',a:['Saat','Spor ayakkabısı','Forma','Top'],correct:1,why:'Şirket üç çizgili ayakkabıyı 1949’da tescil ettirdi.'}]};
